#[path="../crates/core/src/native_game_clock.rs"] mod native_game_clock;
fn main(){
let start=native_game_clock::wall_sample(1100000,0,10000000).unwrap();assert_eq!(start.to_bits(),1038174126);let delta=native_game_clock::frame_delta(1200000,0,10000000,start).unwrap();assert_eq!((delta as f32).to_bits(),1008981771);let mut clock=native_game_clock::GameClock::default();clock.advance_normal(delta).unwrap();assert_eq!(clock.time.to_bits(),1008981771);
let start=native_game_clock::wall_sample(1100000,0,10000000).unwrap();assert_eq!(start.to_bits(),1038174126);let delta=native_game_clock::frame_delta(1100100,0,10000000,start).unwrap();assert_eq!((delta as f32).to_bits(),964891247);let mut clock=native_game_clock::GameClock::default();clock.advance_normal(delta).unwrap();assert_eq!(clock.time.to_bits(),964891247);
let start=native_game_clock::wall_sample(0,0,10000000).unwrap();assert_eq!(start.to_bits(),0);let delta=native_game_clock::frame_delta(2500,0,10000000,start).unwrap();assert_eq!((delta as f32).to_bits(),964891247);let mut clock=native_game_clock::GameClock::default();clock.advance_normal(delta).unwrap();assert_eq!(clock.time.to_bits(),964891247);
let start=native_game_clock::wall_sample(1400000,0,10000000).unwrap();assert_eq!(start.to_bits(),1041194025);let delta=native_game_clock::frame_delta(1600000,0,10000000,start).unwrap();assert_eq!((delta as f32).to_bits(),1017370378);let mut clock=native_game_clock::GameClock::default();clock.advance_normal(delta).unwrap();assert_eq!(clock.time.to_bits(),1017370378);
println!("4 native activation/frame source sequences match Rust wall sample and clock");}
